// PARSE RESPONSE
// ============================================================

let response = pm.response.json();


// ============================================================
// VALIDATE RAILS ARRAY
// ============================================================

pm.test("Rails array should not be empty", function () {

    pm.expect(response.Rails)
        .to.be.an("array")
        .that.is.not.empty;

});


// ============================================================
// CAPTURE ONLY RAIL IDs WHERE Service = "Rail"
// ============================================================

let railIds = [];
let skippedRails = [];

console.log("====================================");
console.log("       RAIL SERVICE VALIDATION");
console.log("====================================");


response.Rails.forEach((rail, index) => {

    let railId = rail.Id;
    let service = rail.Service;

    console.log(
        `Rail ${index + 1} | ID: ${railId} | Service: ${service}`
    );


    // --------------------------------------------------------
    // SERVICE VALIDATION
    // --------------------------------------------------------

    if (service === "Rail") {

        // Store only valid Rail service IDs
        railIds.push(railId);

        console.log(
            `✓ STORED | Rail ID: ${railId} | Service: ${service}`
        );

    } else {

        // Store skipped information for reporting
        skippedRails.push({
            id: railId,
            service: service
        });

        console.log(
            `✗ SKIPPED | Rail ID: ${railId} | Service: ${service}`
        );

    }

});


// ============================================================
// VALIDATE THAT AT LEAST ONE SERVICE = "Rail" EXISTS
// ============================================================

pm.test(
    "At least one Rail with Service = 'Rail' should exist",
    function () {

        pm.expect(
            railIds.length,
            "No Rails found with Service = 'Rail'"
        ).to.be.greaterThan(0);

    }
);


// ============================================================
// STORE VALID RAIL IDs FOR API-2
// ============================================================

pm.collectionVariables.set(
    "railIds",
    JSON.stringify(railIds)
);


// ============================================================
// RESET INDEX BEFORE API-2 STARTS
// ============================================================

pm.collectionVariables.set(
    "railIndex",
    0
);


// ============================================================
// TOTAL VALID RAILS
// ============================================================

pm.collectionVariables.set(
    "totalRails",
    railIds.length
);


// ============================================================
// RESET RAILS WITH TILES
// ============================================================

pm.collectionVariables.set(
    "railsWithTiles",
    0
);


// ============================================================
// RESET EMPTY TILE RAILS
// ============================================================

pm.collectionVariables.set(
    "emptyTileRails",
    JSON.stringify([])
);


// ============================================================
// STORE SKIPPED RAILS
// ============================================================

pm.collectionVariables.set(
    "skippedRails",
    JSON.stringify(skippedRails)
);


// ============================================================
// CONSOLE SUMMARY
// ============================================================

console.log("");
console.log("================================================");
console.log("           RAIL FILTERING SUMMARY");
console.log("================================================");

console.log(
    `Total Rails Received       : ${response.Rails.length}`
);

console.log(
    `Valid Rails (Service=Rail) : ${railIds.length}`
);

console.log(
    `Skipped Rails              : ${skippedRails.length}`
);

console.log("");


if (skippedRails.length > 0) {

    console.log("Skipped Rails:");

    skippedRails.forEach((rail, index) => {

        console.log(
            `${index + 1}. ID: ${rail.id} | Service: ${rail.service}`
        );

    });

} else {

    console.log("Skipped Rails              : None");

}


console.log("");
console.log("Stored Rail IDs:");
console.log(JSON.stringify(railIds));

console.log("================================================");


// ============================================================
// VALIDATE STORED RAIL IDS
// ============================================================

pm.test(
    "All stored Rail IDs should have Service = 'Rail'",
    function () {

        response.Rails.forEach((rail) => {

            if (railIds.includes(rail.Id)) {

                pm.expect(
                    rail.Service,
                    `Service for Rail ID ${rail.Id}`
                ).to.eql("Rail");

            }

        });

    }
);


// ============================================================
// VALIDATE NO DUPLICATE RAIL IDs
// ============================================================

pm.test(
    "Stored Rail IDs should not contain duplicates",
    function () {

        let uniqueRailIds = [...new Set(railIds)];

        pm.expect(
            railIds.length
        ).to.eql(
            uniqueRailIds.length
        );

    }
);

